--
-- Table structure for table `electronic_payment_receipt`
--

DROP TABLE IF EXISTS `electronic_payment_receipt`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `electronic_payment_receipt` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `receipt_no` varchar(80) NOT NULL,
  `bill_id` bigint NOT NULL,
  `payment_order_id` bigint NOT NULL,
  `community_id` bigint NOT NULL,
  `room_no` varchar(50) NOT NULL,
  `payer_name` varchar(100) NOT NULL,
  `bill_type` varchar(60) NOT NULL,
  `period` varchar(30) NOT NULL,
  `pay_channel` varchar(40) NOT NULL,
  `amount` decimal(18,2) NOT NULL,
  `status` varchar(32) NOT NULL,
  `file_url` varchar(300) NOT NULL,
  `checksum` varchar(128) NOT NULL,
  `issued_by` varchar(64) NOT NULL,
  `issued_at` datetime NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `receipt_no` (`receipt_no`),
  UNIQUE KEY `uk_electronic_payment_receipt_order` (`payment_order_id`),
  KEY `idx_electronic_payment_receipt_community` (`community_id`,`issued_at`),
  KEY `idx_electronic_payment_receipt_bill` (`bill_id`)
) ENGINE=InnoDB AUTO_INCREMENT=24 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

